ALTER TABLE `users` ADD `mobile` text NOT NULL DEFAULT '';
ALTER TABLE `users` ADD `account_status` text NOT NULL DEFAULT 'active';
CREATE TABLE `user_roles` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`user_id` integer NOT NULL REFERENCES `users`(`id`),`role_code` text NOT NULL,`effective_from` text NOT NULL,`effective_to` text,`status` text NOT NULL DEFAULT 'pending',`requested_by` integer NOT NULL REFERENCES `users`(`id`),`reviewed_by` integer REFERENCES `users`(`id`),`reviewed_at` text,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE `invoice_verifications` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`invoice_id` integer NOT NULL REFERENCES `factory_invoices`(`id`),`verifier_role` text NOT NULL,`decision` text NOT NULL,`rejection_reason` text,`verified_by` integer NOT NULL REFERENCES `users`(`id`),`verified_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX `invoice_role_verification_unique` ON `invoice_verifications` (`invoice_id`,`verifier_role`);
CREATE TABLE `payment_records` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`payment_request_id` integer NOT NULL REFERENCES `factory_payment_requests`(`id`),`amount_minor` integer NOT NULL,`paid_at` text NOT NULL,`bank_reference` text NOT NULL,`record_type` text NOT NULL DEFAULT 'payment',`reverses_payment_record_id` integer,`recorded_by` integer NOT NULL REFERENCES `users`(`id`),`reviewed_by` integer REFERENCES `users`(`id`),`review_status` text NOT NULL DEFAULT 'not_required',`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE `audit_logs` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`actor_user_id` integer REFERENCES `users`(`id`),`action` text NOT NULL,`module` text NOT NULL,`entity_type` text NOT NULL,`entity_id` text NOT NULL,`business_no` text,`before_json` text,`after_json` text,`ip_address` text,`device_id` text,`sensitive_view` integer NOT NULL DEFAULT 0,`exported` integer NOT NULL DEFAULT 0,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`archive_after` text NOT NULL);
CREATE TABLE `approval_requests` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`request_no` text NOT NULL,`workflow_type` text NOT NULL,`entity_type` text NOT NULL,`entity_id` integer NOT NULL,`summary` text NOT NULL,`payload_json` text NOT NULL,`high_risk` integer NOT NULL DEFAULT 0,`status` text NOT NULL DEFAULT 'pending',`requested_by` integer NOT NULL REFERENCES `users`(`id`),`requested_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`reviewed_by` integer REFERENCES `users`(`id`),`reviewed_at` text,`review_comment` text,`sms_verified_at` text,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX `approval_requests_request_no_unique` ON `approval_requests` (`request_no`);
CREATE TABLE `ai_conversations` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`user_id` integer NOT NULL REFERENCES `users`(`id`),`title` text NOT NULL,`status` text NOT NULL DEFAULT 'active',`retain_until` text NOT NULL,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE `ai_messages` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`conversation_id` integer NOT NULL REFERENCES `ai_conversations`(`id`),`role` text NOT NULL,`content` text NOT NULL,`citation_json` text,`confidence_status` text NOT NULL DEFAULT 'confirmed',`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE `ai_operation_drafts` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`conversation_id` integer NOT NULL REFERENCES `ai_conversations`(`id`),`operation_type` text NOT NULL,`payload_json` text NOT NULL,`high_risk` integer NOT NULL DEFAULT 0,`status` text NOT NULL DEFAULT 'draft',`confirmed_by` integer REFERENCES `users`(`id`),`confirmed_at` text,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE `file_objects` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`object_key` text NOT NULL,`file_name` text NOT NULL,`content_type` text NOT NULL,`size_bytes` integer NOT NULL,`category` text NOT NULL,`entity_type` text,`entity_id` text,`owner_user_id` integer NOT NULL REFERENCES `users`(`id`),`factory_id` integer REFERENCES `factories`(`id`),`supplier_id` integer REFERENCES `suppliers`(`id`),`sensitive` integer NOT NULL DEFAULT 0,`retain_until` text,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX `file_objects_object_key_unique` ON `file_objects` (`object_key`);
CREATE TABLE `import_batches` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`import_no` text NOT NULL,`type` text NOT NULL,`file_object_id` integer REFERENCES `file_objects`(`id`),`file_name` text NOT NULL,`fingerprint` text NOT NULL,`business_key` text,`status` text NOT NULL DEFAULT 'preview',`total_rows` integer NOT NULL DEFAULT 0,`valid_rows` integer NOT NULL DEFAULT 0,`error_count` integer NOT NULL DEFAULT 0,`warning_count` integer NOT NULL DEFAULT 0,`duplicate_of_batch_id` integer,`committed_by` integer REFERENCES `users`(`id`),`committed_at` text,`created_by` integer NOT NULL REFERENCES `users`(`id`),`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX `import_batches_import_no_unique` ON `import_batches` (`import_no`);
CREATE TABLE `import_staging_rows` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`import_batch_id` integer NOT NULL REFERENCES `import_batches`(`id`),`sheet_name` text NOT NULL,`source_row_no` integer NOT NULL,`business_key` text,`normalized_json` text NOT NULL,`raw_json` text NOT NULL,`validation_status` text NOT NULL,`validation_messages_json` text NOT NULL DEFAULT '[]',`mapping_confirmed` integer NOT NULL DEFAULT 0);
CREATE TABLE `reminder_schedules` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`reminder_type` text NOT NULL,`entity_type` text NOT NULL,`entity_id` integer NOT NULL,`business_no` text,`due_at` text NOT NULL,`next_run_at` text NOT NULL,`recurrence` text NOT NULL,`milestone_days_json` text NOT NULL DEFAULT '[]',`recipient_role_json` text NOT NULL,`recipient_user_ids_json` text NOT NULL DEFAULT '[]',`channels_json` text NOT NULL DEFAULT '["in_app","email"]',`severity` text NOT NULL DEFAULT 'normal',`quiet_hours_bypass` integer NOT NULL DEFAULT 0,`status` text NOT NULL DEFAULT 'active',`last_run_at` text,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE `notification_messages` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`recipient_user_id` integer REFERENCES `users`(`id`),`recipient_role` text,`recipient_factory_id` integer REFERENCES `factories`(`id`),`recipient_supplier_id` integer REFERENCES `suppliers`(`id`),`channel` text NOT NULL,`type` text NOT NULL,`severity` text NOT NULL,`title` text NOT NULL,`message` text NOT NULL,`entity_type` text NOT NULL,`entity_id` integer NOT NULL,`business_no` text,`status` text NOT NULL DEFAULT 'queued',`sent_at` text,`read_at` text,`error_message` text,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE `auth_credentials` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`user_id` integer NOT NULL REFERENCES `users`(`id`),`password_hash` text NOT NULL,`password_salt` text NOT NULL,`failed_attempts` integer NOT NULL DEFAULT 0,`locked_at` text,`password_changed_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX `auth_credentials_user_id_unique` ON `auth_credentials` (`user_id`);
CREATE TABLE `auth_challenges` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`challenge_no` text NOT NULL,`user_id` integer NOT NULL REFERENCES `users`(`id`),`purpose` text NOT NULL,`code_hash` text NOT NULL,`device_id` text NOT NULL,`ip_address` text,`region` text,`expires_at` text NOT NULL,`attempts` integer NOT NULL DEFAULT 0,`verified_at` text,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX `auth_challenges_challenge_no_unique` ON `auth_challenges` (`challenge_no`);
CREATE TABLE `trusted_devices` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`user_id` integer NOT NULL REFERENCES `users`(`id`),`device_id` text NOT NULL,`device_name` text NOT NULL DEFAULT '',`last_ip_address` text,`last_region` text,`trusted_until` text NOT NULL,`revoked_at` text,`last_used_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX `trusted_user_device_unique` ON `trusted_devices` (`user_id`,`device_id`);
CREATE TABLE `auth_sessions` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`user_id` integer NOT NULL REFERENCES `users`(`id`),`token_hash` text NOT NULL,`device_id` text NOT NULL,`ip_address` text,`region` text,`expires_at` text NOT NULL,`revoked_at` text,`last_seen_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP,`created_at` text NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX `auth_sessions_token_hash_unique` ON `auth_sessions` (`token_hash`);
